async (suffix = 'Conduit') => {
  const baseUrl = pm.collectionVariables.get('url');
  const slug = pm.collectionVariables.get(`slug${suffix}`);
  const token = pm.collectionVariables.get(`token${suffix}`);
 
  if (!slug || !token) {
    console.warn(`deleteArticle: no slug or token for suffix "${suffix}"`);
    return;
  }
 
  const requestStructure = {
    url: `${baseUrl}articles/${slug}`,
    method: 'DELETE',
    header: {
      Authorization: `Token ${token}`,
    },
  };
 
  const response = await pm.sendRequest(requestStructure);
 
  if (response.code !== 204 && response.code !== 404) {
    console.warn(`deleteArticle failed with status ${response.code}: ${response.text()}`);
  }
}

